import { Fragment } from 'react/jsx-runtime';
import { WalletType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const IssueWalletIntroPage = () => {
  const { navigate } = useNavigate();
  const walletType = WalletType.개인;

  const handleClick = () => {
    navigate(PATHS.issueWallet.inputBankAccount, { replace: false, state: { walletType } });
  };

  return (
    <Fragment>
      <div className="content sub has-btm-btn">
        <div className="sub-desc">
          <p
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:createMyWalletPrompt'),
            }}
          ></p>
        </div>
        <div className="sel-wallet info">
          <p>{i18n.t('text:walletCreationSteps')}</p>
          <div className="wallet-create-step">
            <ul className="step-list">
              <li className="step-box accnt">
                <div className="step-icon">&nbsp;</div>
                <p
                  dangerouslySetInnerHTML={{
                    __html: i18n.t('bankAccountVerificationAndLinking'),
                  }}
                ></p>
              </li>
              <li className="arr">
                <i className="icon">{i18n.t('nextStep')}</i>
              </li>
              {walletType === 'personal' ? (
                <li className="step-box persnal">
                  <div className="step-icon">&nbsp;</div>
                  <p>{i18n.t('idVerification')}</p>
                </li>
              ) : (
                <li className="step-box company">
                  <div className="step-icon">&nbsp;</div>
                  <p
                    dangerouslySetInnerHTML={{
                      __html: i18n.t('businessRegistrationVerification'),
                    }}
                  ></p>
                </li>
              )}
              <li className="arr">
                <i className="icon">{i18n.t('nextStep')}</i>
              </li>
              <li className="step-box wallet">
                <div className="step-icon">&nbsp;</div>
                <p>{i18n.t('walletCreation')}</p>
              </li>
            </ul>
          </div>
        </div>
      </div>
      <div className="btm-btn-area">
        <button type="button" onClick={handleClick} className="btm-btn app">
          {i18n.t('createWallet')}
        </button>
      </div>
    </Fragment>
  );
};
